// Changes: Tests of the PNG canvas scale (sharp 2× for small tables, within the browsers' side and area limits).

import { describe, expect, it } from 'vitest'
import { MAX_CANVAS_AREA, MAX_CANVAS_SIDE, canvasScale } from './png'

const fits = (w: number, h: number) => {
  const s = canvasScale(w, h)
  const W = Math.round(w * s)
  const H = Math.round(h * s)
  return W <= MAX_CANVAS_SIDE && H <= MAX_CANVAS_SIDE && W * H <= MAX_CANVAS_AREA
}

describe('canvasScale', () => {
  it('draws small tables at 2× for sharpness', () => {
    expect(canvasScale(800, 400)).toBe(2)
  })

  it('stays within the canvas area limit of iOS Safari (~16.7 Mpx) for a big table', () => {
    // 3500 × 3000 CSS px fits each side at 2× but is 42 Mpx.
    expect(canvasScale(3500, 3000)).toBeLessThan(2)
    expect(fits(3500, 3000)).toBe(true)
    expect(MAX_CANVAS_AREA).toBeLessThanOrEqual(16_777_216)
  })

  it('shrinks below 1× when even the plain size is too big', () => {
    expect(fits(20000, 900)).toBe(true)
    expect(fits(6000, 6000)).toBe(true)
  })
})
